export function restoreTicketOptionalProgressiveLoading(path, source) {
  const name = path.split("/").at(-1)?.replace(/\.tsx$/, "");
  for (const change of changes[name] || []) {
    assert.equal(source.split(change.after).length - 1, 1, `Reviewed optional availability edit drifted: ${name}`);
    source = source.replace(change.after, change.before);
  }
  return source;
}
